import openpyxl
out='/tmp/llm_rollout_415204so/2_3048_answer_template_8786_input_filled.xlsx'
gold='/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/2_3048_answer_template_8786_golden.xlsx'
wb = openpyxl.load_workbook(out, data_only=False)
wg = openpyxl.load_workbook(gold, data_only=False)
formulas_out=[]
formulas_gold=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, str) and c.value.startswith('='):
                formulas_out.append((ws.title, c.coordinate, c.value))
for ws in wg.worksheets:
    for row in ws.iter_rows():
        for c in row:
            if isinstance(c.value, str) and c.value.startswith('='):
                formulas_gold.append((ws.title, c.coordinate, c.value))
print('out formulas', len(formulas_out))
print('gold formulas', len(formulas_gold))
for a,b in zip(formulas_out, formulas_gold):
    if a != b:
        print('DIFF', a, b)
print('formulas identical:', formulas_out==formulas_gold)

# check calculated values from data_only open (cached by openpyxl? data_only just reads cached <v>)
wbd = openpyxl.load_workbook(out, data_only=True)
wgd = openpyxl.load_workbook(gold, data_only=True)
mism=[]
for ws in wbd.worksheets:
    for row in ws.iter_rows():
        for c in row:
            v=wgd[ws.title][c.coordinate].value
            if c.value != v:
                mism.append((ws.title,c.coordinate,c.value,v))
print('cached-value mismatches:', len(mism))
for m in mism[:20]: print(m)
